custom_css:
/* Synthetic beautification theme written for tests (not a real published theme). */
@import url("https://fonts.example.com/sample-serif.css");

:root {
    --s-weight: 0;  /* 0 = flat page, 1 = cards */
}

:root {
    --s-paper: #F7FAF6;
    --s-paper-rgb: 247, 250, 246;
    --s-surface: #FBFDFA;
    --s-sunken: #E8EFE6;
    --s-line: #D3DED0;
    --s-secondary: #5E7360;
    --s-ink: #22302A;
    --s-accent: #3F7A5C;
    color-scheme: light;
}

@media (prefers-color-scheme: dark) {
    :root {
        --s-paper: #121815;
        --s-paper-rgb: 18, 24, 21;
        --s-surface: #1A221E;
        --s-sunken: #0D120F;
        --s-line: #2C3832;
        --s-secondary: #94A89A;
        --s-ink: #E2ECE5;
        --s-accent: #8CC7A6;
        color-scheme: dark;
    }
}

:root {
    --s-serif: "Noto Serif SC", "Songti SC", ui-serif, Georgia, serif;
    --s-sans: -apple-system, "PingFang SC", "Noto Sans SC", sans-serif;
    --s-body: var(--s-serif);
    --s-radius: 12px;
}

:root {
    --SmartThemeBodyColor: var(--s-ink) !important;
    --SmartThemeEmColor: var(--s-secondary) !important;
    --SmartThemeUnderlineColor: var(--s-accent) !important;
    --SmartThemeQuoteColor: var(--s-accent) !important;
    --SmartThemeBlurTintColor: var(--s-surface) !important;
    --SmartThemeChatTintColor: rgba(var(--s-paper-rgb), calc(0.96 * (1 - var(--s-weight)))) !important;
    --SmartThemeUserMesBlurTintColor: var(--s-sunken) !important;
    --SmartThemeBotMesBlurTintColor: var(--s-surface) !important;
    --SmartThemeShadowColor: transparent !important;
    --SmartThemeBorderColor: var(--s-line) !important;
    --mainFontFamily: var(--s-sans) !important;
}

html, body {
    background-color: var(--s-paper) !important;
}

.mes_text {
    font-family: var(--s-body);
    color: var(--s-ink);
    padding: 4px 0 !important;
}

#top-bar {
    position: fixed;
    top: 0;
    width: 100%;
    height: 44px;
    background: transparent !important;
}

#sheld {
    width: 60vw;
    max-width: 900px;
    margin: 0 auto;
}

#send_form {
    display: flex;
    position: relative;
    border-radius: 999px !important;
    background: var(--s-surface) !important;
    padding: 6px 10px !important;
    margin: 8px 12px;
    transform: translateY(-4px);
}

#nonQRFormItems::before {
    content: "~";
    position: absolute;
    left: 50%;
    top: -12px;
    color: var(--s-accent);
}

.mes {
    border-radius: var(--s-radius);
    margin-bottom: 10px;
    & .mes_block { min-width: 0; overflow: hidden; }
}

.menu_button {
    display: inline-flex;
    justify-content: center;
    align-items: center;
    border-radius: var(--s-radius) !important;
    color: var(--s-ink);
}

#rm_print_characters_block {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
}

.drawer-icon.fa-bars::before { content: "\f0c9"; }

@keyframes s-fade { from { opacity: 0 } to { opacity: 1 } }
